import sys,yaml,numpy as np; from PIL import Image; from pathlib import Path; d=Path('assets/default/map/tiles'); m=yaml.safe_load(open(d/'manifest.yaml',encoding='utf-8')); es=m if isinstance(m,list) else m.get('assets',[]); ch=lambda f: (lambda a: ((a[...,:3]*(a[...,3:4]/255.0)).mean(-1), a[...,3]))(np.asarray(Image.open(f).convert('RGBA'),dtype=np.float64)); rh=lambda x: np.abs(x[:,0]-x[:,-1]).mean()/max(float(np.median(np.abs(np.diff(x,axis=1)).mean(0))),0.5); rv=lambda x: rh(x.T); bad=[]; n={'tile':0,'strip':0}
for e in es:
    f=d/str(e.get('file',''))
    if isinstance(e.get('tile'),dict):
        n['tile']+=1; L,A=ch(f); r=max(rh(L),rv(L),rh(A),rv(A))
        if r>2.5: bad.append((e.get('id'),'tile',round(r,2)))
    elif isinstance(e.get('strip'),dict):
        n['strip']+=1; L,A=ch(f); r=max(rh(L),rh(A)); edge=float(max(A[:2].max(),A[-2:].max()))
        if r>2.5 or edge>0: bad.append((e.get('id'),'strip',round(r,2),edge))
print(n,'seam_bad',bad[:10]); sys.exit(1 if bad or not n['tile'] or not n['strip'] else 0)
